import { MakeLogicType, actions, afterMount, connect, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { visionAlertsEventsList } from '../generated/api'
import type { VisionAlertEventApi } from '../generated/api.schemas'

export interface ScannerAlertEventsLogicProps {
    alertId: string
}

export interface AlertEventsPage {
    results: VisionAlertEventApi[]
    next: string | null
    count: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertEventsLogicValues {
    currentTeamId: number | null // teamLogic
    eventsPage: AlertEventsPage
    eventsPageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertEventsLogicActions {
    loadEvents: () => any
    loadEventsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEventsSuccess: (
        eventsPage: {
            count: number
            next: string | null
            results: VisionAlertEventApi[]
        },
        payload?: any
    ) => {
        eventsPage: {
            count: number
            next: string | null
            results: VisionAlertEventApi[]
        }
        payload?: any
    }
    loadMore: () => {
        value: true
    }
    loadMoreFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMoreSuccess: (
        eventsPage: AlertEventsPage,
        payload?: {
            value: true
        }
    ) => {
        eventsPage: AlertEventsPage
        payload?: {
            value: true
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertEventsLogicMeta {
    key: string
}

export type scannerAlertEventsLogicType = MakeLogicType<
    scannerAlertEventsLogicValues,
    scannerAlertEventsLogicActions,
    ScannerAlertEventsLogicProps,
    scannerAlertEventsLogicMeta
>

export const scannerAlertEventsLogic = kea<scannerAlertEventsLogicType>([
    path((key) => ['products', 'replay_vision', 'frontend', 'replay_scanners', 'scannerAlertEventsLogic', key]),
    props({} as ScannerAlertEventsLogicProps),
    key((props) => props.alertId),

    connect({
        values: [teamLogic, ['currentTeamId']],
    }),

    actions({
        loadMore: true,
    }),

    loaders(({ props, values }) => ({
        eventsPage: [
            { results: [], next: null, count: 0 } as AlertEventsPage,
            {
                loadEvents: async () => {
                    const response = await visionAlertsEventsList(String(values.currentTeamId), props.alertId)
                    return {
                        results: response.results ?? [],
                        next: response.next ?? null,
                        count: response.count ?? 0,
                    }
                },
                loadMore: async () => {
                    const nextUrl = values.eventsPage.next
                    if (!nextUrl) {
                        return values.eventsPage
                    }
                    const res = await fetch(nextUrl, { credentials: 'include' })
                    if (!res.ok) {
                        throw new Error(`Failed to load more events: ${res.status} ${res.statusText}`)
                    }
                    const data = (await res.json()) as {
                        results?: VisionAlertEventApi[]
                        next?: string | null
                        count?: number
                    }
                    return {
                        results: [...values.eventsPage.results, ...(data.results ?? [])],
                        next: data.next ?? null,
                        count: data.count ?? values.eventsPage.count,
                    }
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadEvents()
    }),
])
